var doc = Document;
// Goal: make a repeated assembly (here one wall standing in for furniture) as a group, place it
// twice, then change it once so every placed copy updates. All writes in one block.
// A blank project has levels already; take the lowest one rather than creating another.
Autodesk.Revit.DB.Level level = null;
foreach (Autodesk.Revit.DB.Level l in new Autodesk.Revit.DB.FilteredElementCollector(doc).OfClass(typeof(Autodesk.Revit.DB.Level))) {
  if (level == null || l.Elevation < level.Elevation) level = l;
}

double z = level.Elevation;
return Connector.WithTransaction(doc, () => {
  // 1. Create the members and group them. NewGroup takes element ids and returns the placed Group;
  //    its GroupType is the reusable definition.
  var wall = Autodesk.Revit.DB.Wall.Create(doc,
      Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 0, z), new Autodesk.Revit.DB.XYZ(10, 0, z)), level.Id, false);
  doc.Regenerate();
  var group1 = doc.Create.NewGroup(new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { wall.Id });
  doc.Regenerate();
  var originalTypeId = group1.GroupType.Id;

  // 2. Place a second instance elsewhere from the same GroupType.
  var group2 = doc.Create.PlaceGroup(new Autodesk.Revit.DB.XYZ(0, 60, z), group1.GroupType);
  doc.Regenerate();
  var group2Id = group2.Id;

  // 3. Move a placed instance: pass the GROUP's id to MoveElement. Passing a member's own id does
  //    nothing at all (no error, no warning, no effect).
  var before = ((doc.GetElement(group2Id) as Autodesk.Revit.DB.Group).GetMemberIds());
  Autodesk.Revit.DB.ElementId memberId = null;
  foreach (var id in before) memberId = id;
  var memberBefore = ((doc.GetElement(memberId) as Autodesk.Revit.DB.Wall).Location as Autodesk.Revit.DB.LocationCurve).Curve.GetEndPoint(0);
  Autodesk.Revit.DB.ElementTransformUtils.MoveElement(doc, memberId, new Autodesk.Revit.DB.XYZ(5, 0, 0));
  doc.Regenerate();
  var memberAfterMemberMove = ((doc.GetElement(memberId) as Autodesk.Revit.DB.Wall).Location as Autodesk.Revit.DB.LocationCurve).Curve.GetEndPoint(0);
  bool memberMoveDidNothing = memberAfterMemberMove.IsAlmostEqualTo(memberBefore);
  Autodesk.Revit.DB.ElementTransformUtils.MoveElement(doc, group2Id, new Autodesk.Revit.DB.XYZ(5, 0, 0));
  doc.Regenerate();
  var memberAfterGroupMove = ((doc.GetElement(memberId) as Autodesk.Revit.DB.Wall).Location as Autodesk.Revit.DB.LocationCurve).Curve.GetEndPoint(0);
  bool groupMoveWorked = System.Math.Abs(memberAfterGroupMove.X - memberBefore.X - 5.0) < 0.001;

  // 4. Edit the group. Editing a member in place is refused once two or more instances exist
  //    ("Changes to groups are allowed only in group edit mode"; the run rolls back). Instead:
  //    ungroup ONE instance (its members become loose elements), edit them freely, and regroup.
  var looseIds = group1.UngroupMembers();
  Autodesk.Revit.DB.ElementId looseWallId = null;
  foreach (var id in looseIds) { if (doc.GetElement(id) is Autodesk.Revit.DB.Wall) looseWallId = id; }
  var lc = (doc.GetElement(looseWallId) as Autodesk.Revit.DB.Wall).Location as Autodesk.Revit.DB.LocationCurve;
  lc.Curve = Autodesk.Revit.DB.Line.CreateBound(new Autodesk.Revit.DB.XYZ(0, 0, z), new Autodesk.Revit.DB.XYZ(16, 0, z));
  doc.Regenerate();

  // 5. Regroup: NewGroup mints a NEW GroupType that reflects the edit.
  var newType = doc.Create.NewGroup(new System.Collections.Generic.List<Autodesk.Revit.DB.ElementId> { looseWallId }).GroupType;
  doc.Regenerate();

  // 6. Propagate: set Group.GroupType on every other instance. Revit re-creates their members, so
  //    ids captured before this step no longer resolve; call GetMemberIds() again afterwards.
  (doc.GetElement(group2Id) as Autodesk.Revit.DB.Group).GroupType = newType;
  doc.Regenerate();
  double group2WallLength = 0;
  foreach (var id in (doc.GetElement(group2Id) as Autodesk.Revit.DB.Group).GetMemberIds()) {
    if (doc.GetElement(id) is Autodesk.Revit.DB.Wall w) group2WallLength = (w.Location as Autodesk.Revit.DB.LocationCurve).Curve.Length;
  }

  // 7. Verify by comparing against the definition, not against absolute coordinates: a placed
  //    instance's members are offset from the origin argument. Both instances now share the type
  //    and the second one's wall has the edited length.
  return new {
    originalGroupTypeId = originalTypeId.Value, newGroupTypeId = newType.Id.Value,
    memberMoveDidNothing, groupMoveWorked,
    group2WallLength, propagated = System.Math.Abs(group2WallLength - 16.0) < 0.001,
    group2UsesNewType = (doc.GetElement(group2Id) as Autodesk.Revit.DB.Group).GroupType.Id == newType.Id
  };
});
